    @EventHandler( payloadType=CreateInventoryItemEvent.class )
    public void handle( CreateInventoryItemEvent event) {
	    LOGGER.info("handling CreateInventoryItemEvent - " + event );
	    InventoryItem entity = new InventoryItem();
            entity.setInventoryItemId( event.getInventoryItemId() );
            entity.setQuantityOnHand( event.getQuantityOnHand() );
            entity.setQuantityReserved( event.getQuantityReserved() );
            entity.setSafetyStock( event.getSafetyStock() );
            entity.setStatus( event.getStatus() );
	    
    	// ------------------------------------------
    	// persist a new one
    	// ------------------------------------------ 
	    create(entity);
        
        // ------------------------------------------
    	// emit to subscribers that find all
    	// ------------------------------------------    	
        emitFindAllInventoryItem( entity );
    }

